// src/cli/store.ts
var REVIEW_FORMAT = "family-finance-review/review@1";
function dataDir(flag) {
	return resolve(flag ?? process.env.FFR_DIR ?? join(homedir(), ".family-finance-review"));
}
var reviewsDir = (dir) => join(dir, "reviews");
var reviewPath = (dir, date) => join(reviewsDir(dir), `${date}.json`);
function readReview(path) {
	const file = JSON.parse(readFileSync(path, "utf8"));
	if (file.format !== "family-finance-review/review@1") throw new Error(`${path} is not a review file (expected "format": "${REVIEW_FORMAT}").`);
	const { format: _format, savedAt: _savedAt, ...snapshot } = file;
	return snapshot.flows ? {
		...snapshot,
		cashflow: deriveCashflow(snapshot.flows, snapshot.baseCurrency, snapshot.usdCny)
	} : snapshot;
}
/** All saved reviews, oldest first. */
function loadReviews(dir) {
	const folder = reviewsDir(dir);
	if (!existsSync(folder)) return [];
	return readdirSync(folder).filter((name) => /^\d{4}-\d{2}-\d{2}\.json$/.test(name)).sort().map((name) => readReview(join(folder, name)));
}
function writeReview(dir, snapshot) {
	mkdirSync(reviewsDir(dir), { recursive: true });
	const file = {
		format: REVIEW_FORMAT,
		savedAt: (/* @__PURE__ */ new Date()).toISOString(),
		...snapshot
	};
	const path = reviewPath(dir, snapshot.date);
	writeFileSync(path, `${JSON.stringify(file, null, 2)}\n`);
	return path;
}
function writeText(path, text) {
	mkdirSync(resolve(path, ".."), { recursive: true });
	writeFileSync(path, text);
	return path;
}
